        let _ = request(&mut tui, &Command::SetMode { mode: Mode::Normal }).await;
        let snap = request(&mut tui, &Command::Undo).await;
        assert_eq!(
            snap.text, "",
            "undo 1回でセッション全体が戻る（agent の切断がグループを壊していない）"
