/// として [`Editor::apply`] に渡し、フォーカス中の View の文書と選択を更新する。
#[derive(Clone, Debug)]
pub struct Editor {
    documents: BTreeMap<DocumentId, Document>,
    histories: BTreeMap<DocumentId, History>,
