    /// 空のスクラッチ文書と1つの View を持つエディタを作る。
    pub fn new() -> Self {
        let scratch = DocumentId(0);
        let mut editor = Self {
            documents: BTreeMap::new(),
            histories: BTreeMap::new(),
            paths: BTreeMap::new(),
            dirty: BTreeSet::new(),
